import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Plugin runtimes and trust limits","description":"","frontmatter":{"title":"Plugin runtimes and trust limits","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","order":260},"headers":[],"relativePath":"en/developer/plugins/runtimes.md","filePath":"en/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),n={name:"en/developer/plugins/runtimes.md"};function r(d,e,o,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">Plugin runtimes and trust limits <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;Plugin runtimes and trust limits {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Select an executable format whose dependencies and trust match the host. Read <a href="./">plugin overview</a>, validate the manifest against the actual build and inspect target-specific restrictions before loading code. Protocol compatibility, native ABI compatibility and permission grants are independent checks.</p><h2 id="choose-an-implemented-runtime" tabindex="-1">Choose an implemented runtime <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;Choose an implemented runtime {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime</th><th>Execution</th><th>Trust and portability</th></tr></thead><tbody><tr><td><code>native</code></td><td><code>libloading</code> C ABI</td><td>Trusted in-process code; target-specific</td></tr><tr><td><code>process</code></td><td>Standalone executable, framed stdin/stdout</td><td>Crash isolation, ordinary user OS permissions</td></tr><tr><td><code>napi-vm</code></td><td>Ahead-of-time JS on QuickJS via <code>rquickjs</code></td><td>Denied host effects by default; optional native addons change trust</td></tr><tr><td><code>declarative</code></td><td>Validated integration descriptors</td><td>No guest program; effects use host broker</td></tr><tr><td><code>wasm</code></td><td>Optional runtime slot</td><td>General engine not enabled in normal builds</td></tr></tbody></table><p>Native ABI v1 exchanges serialized bytes through a small C table; Rust containers, trait objects and futures do not cross it. Native libraries remain loaded until shutdown. Process framing uses a little-endian u32 length followed by JSON bytes, not newline-delimited control RPC. Keep diagnostic output away from the framed stdout channel.</p><h2 id="understand-quickjs-compatibility" tabindex="-1">Understand QuickJS compatibility <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;Understand QuickJS compatibility {#understand-quickjs-compatibility}&quot;">​</a></h2><p>The manifest name <code>napi-vm</code> remains stable, but old claims about a separate pure-Rust interpreter are historical. Guests get the documented compatibility globals, not a complete Node environment. <code>napi_get_uv_event_loop</code> is unsupported. Native <code>.node</code> addons use a deliberately trusted, allowlisted and SHA-256-verified in-process path; they are not made safe by the JavaScript runtime name.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>Use focused loader tests when a full native-addon fixture would require unavailable platform tools.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Manifest parsing rejects unsupported protocol/ABI combinations before loading. Android permits portable QuickJS and valid Android/Bionic process entries, but rejects native dynamic libraries and <code>.node</code> addons. A desktop Linux/glibc artifact is not an Android process plugin.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>Restart a private host after replacing a native library. If startup times out and becomes uncertain, the manager can retain the worker identity and block replacement; do not bypass that state by declaring shutdown successful. Event buffers are bounded and delivery may report lag; startup emission is not a durable queue. The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">loader implementation</a> owns the current engine and lifecycle behavior.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Current loader limits are 512 MiB QuickJS memory, 2 MiB stack, per-call interruption budgets, 16 MiB protocol frames and up to 128 queued calls per instance. These are implementation limits, not an effects cancellation guarantee. A timed-out process is terminated/removed; a timed-out native call cannot be safely killed and its instance is retained. Native OS effects may already have happened. Inspect the original outcome and lifecycle before replacement/retry. Trusted <code>.node</code> addons run with host-process privileges, outside the JavaScript capability boundary.</p>`,16)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
